(()=>{'use strict';if(document.getElementById('guide-lang-switch'))return;const isTR=location.pathname.replace(/\/+$/,'').endsWith('/tr');const s=document.createElement('style');s.textContent=`#guide-lang-switch{position:fixed;top:max(10px,env(safe-area-inset-top));right:12px;z-index:9999;display:flex;gap:3px;padding:4px;background:rgba(255,255,255,.94);border:1px solid rgba(23,32,42,.14);border-radius:999px;box-shadow:0 5px 18px rgba(23,32,42,.12);backdrop-filter:blur(10px)}#guide-lang-switch a{min-width:34px;padding:7px 9px;border-radius:999px;text-align:center;text-decoration:none;font:800 12px/1 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:#17202a}#guide-lang-switch a.active{background:#17202a;color:white}@media(max-width:640px){#guide-lang-switch{top:max(7px,env(safe-area-inset-top));right:8px}#guide-lang-switch a{padding:7px 8px}}`;document.head.appendChild(s);const n=document.createElement('nav');n.id='guide-lang-switch';n.setAttribute('aria-label',isTR?'Dil seçimi':'Выбор языка');n.innerHTML=`<a href="/england-trip-guide/" class="${isTR?'':'active'}" lang="ru">RU</a><a href="/england-trip-guide/tr/" class="${isTR?'active':''}" lang="tr">TR</a>`;document.body.appendChild(n);})();